    {% set push_dirs = ['5', '6', '7', '5.0', '6.0', '7.0', '三', '遊', '左'] if is_left else ['3', '4', '9', '3.0', '4.0', '9.0', '一', '二', '右'] %}
    {% set no_runners = ['なし', '0', '0.0'] %}
    {% set loaded_runners = ['満塁', 'F'] %}
    {% set risp_runners = ['2塁', '3塁', '1,2塁', '1,3塁', '2,3塁', '満塁', '2', '3', '1.2', '1.3', '2.3', 'F'] %}
{% include 'parts/current_year_stats/hit_stats_separator.njk' %}    {% set hit_results = ['H', '1B', '2B', '3B', 'HR', '単打', '2BH', '3BH', '本塁打'] %}
    {% set ab_results = ['H', '1B', '2B', '3B', 'HR', 'O', 'E', 'FC', 'K', '単打', '2BH', '3BH', '本塁打', 'ゴロ', 'フライ', 'ライナー', '三振', '失策出塁', '敵失', '野手選択', '併殺打'] %}
{% include 'parts/current_year_stats/plate_stats.njk' %}    {% set game_hit_counts = {} %}
    {% set game_has_hit = {} %}
{% include 'parts/current_year_stats/game_hit_counts.njk' %}    {% set total_hit_games = game_has_hit|length %}
    {% set multi_hit_games = namespace(count=0) %}
{% include 'parts/current_year_stats/multi_hit_counts.njk' %}    {% macro format_avg(h, ab) %}{% if ab > 0 %}{% set a = h / ab %}{% set v = "%.3f"|format(a) %}{% if a < 1 %}.{{ sliceText(v, 2) }}{% else %}{{ v }}{% endif %}{% else %}.000{% endif %}{% endmacro %}
    {% macro format_diff(h1, ab1, h_all, ab_all) %}{% if ab1 > 0 and ab_all > 0 %}{% set d = (h1 / ab1) - (h_all / ab_all) %}{% set sign = "" if d < 0 else "+" %}{% set v = "%.3f"|format(d|abs) %}{% set fv = sign ~ ("." ~ sliceText(v, 2) if d|abs < 1 else v) %}{% if d < 0 %}<span style="color: red;">-{{ fv|replace("+-", "") }}</span>{% else %}{{ fv }}{% endif %}{% else %}-{% endif %}{% endmacro %}
{% include 'parts/current_year_stats/summary_and_table_head.njk' %}                    {% set displayed_multi = {} %}
{% include 'parts/current_year_stats/plate_rows.njk' %}

parts/current_year_stats/game_hit_counts:
{% for r in records %}
    {% set res_str = r.result|string %}
    {% if res_str in hit_results %}
        {% set gid = r.game_date|string ~ '_' ~ r.game_id|string %}
        {% set _ = putDict(game_has_hit, gid, true) %}
        {% if gid in game_hit_counts %}
            {% set _ = putDict(game_hit_counts, gid, game_hit_counts[gid] + 1) %}
        {% else %}
            {% set _ = putDict(game_hit_counts, gid, 1) %}
        {% endif %}
    {% endif %}
{% endfor %}

parts/current_year_stats/multi_hit_count:
{% for gid, count_h in game_hit_counts.items() %}
    {% if count_h >= 2 %}{% set _ = setAttr(multi_hit_games, "count", multi_hit_games.count + 1) %}{% endif %}
{% endfor %}

