        if (result instanceof HTMLElement) {
            if (result.tagName === 'SELECT') {
                const attrKey = col.n === "弾道" ? 'dan' : col.n === "ケガしにくさ" ? 'injury' : col.n === "送球" ? 'throw' : 'catcher';

                result.addEventListener('change', (e) => {
                    const val = e.target.value;
                    if (attrKey === 'dan') {
                        e.target.style.color = trajColors[val];
                    } else {
                        e.target.className = `rank-${val}`; 
                    }
                    // ★ localStorageではなくサーバーへ直接送信！
                    updateAttr(p.player_id || p.id || p.no, attrKey, val, e.target);
                });
            }
