            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ player_id: playerId, attr: attrKey, value: val })
        });
        if (res.ok) {
            selectElement.style.backgroundColor = '#d4edda'; // 成功
            setTimeout(() => { selectElement.style.backgroundColor = originalBg; }, 800);
        } else {
            alert('保存に失敗しました。');
            selectElement.style.backgroundColor = '#f8d7da'; // 失敗
        }
    } catch (e) {
